css:
@page {
    size: A4;
    margin: 0 !important;
    padding: 0 !important;
}

body {
    margin: 0 !important;
    padding: 0 !important;
    font-family: "Times New Roman", serif;
    font-size: 15px;
    line-height: 1.6;
    color: #000;
    width: 100% !important;
    height: 100% !important;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    height: 100% !important;
}

.page {
    position: relative;
    width: 100vw !important;
    height: 100vh !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden;
    box-sizing: border-box;
}

.page img.bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    z-index: 1;
    margin: 0;
    padding: 0;
    border: none;
    outline: none;
    image-rendering: -webkit-optimize-contrast;
    image-rendering: crisp-edges;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* Center content block vertically */
.page .content {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 78%;
    z-index: 2;
    box-sizing: border-box;
    text-align: justify;
}

/* Rest of your CSS remains the same */
.content h2 {
    margin-bottom: 18px;
    font-size: 22px;
    font-weight: bold;
    text-align: center;
}

.content p {
    margin: 0 0 14px 0;
    font-size: 15px;
    text-align: justify;
    text-indent: 30px;
}

.details p {
    text-indent: 0;
    margin: 0 0 10px 0;
}
